package org.sleepwell.app;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;
/** Saved tag management and descriptive record comparison, no inferred sleep or causal promise. */
public final class TagManagementActivity extends Activity {
 TagJobs.Job job;TagJobs.State drawn;String selected="",renameDraft="";boolean resumed;Dialog dialog;EditText rename;final Handler main=new Handler(Looper.getMainLooper());
 @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);selected=state==null?getIntent().getStringExtra("tag"):state.getString("tag","");if(selected==null)selected="";job=TagJobs.get(this,Records.factory);if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::finish);render();if(state!=null&&state.getBoolean("renaming")){renameDraft=state.getString("rename",selected);openRename(renameDraft);}}
 @Override protected void onResume(){super.onResume();resumed=true;job.inspect();poll.run();}@Override protected void onPause(){resumed=false;main.removeCallbacks(poll);super.onPause();}
 final Runnable poll=new Runnable(){public void run(){if(!resumed)return;if(drawn!=job.state)render();main.postDelayed(this,100);}};
 void render(){TagJobs.State s=job.state;drawn=s;LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Tags & sleep",this::finish);Design.space(body,10);if(s.busy){Design.text(body,"Reading or updating saved tags…",14,400,Design.MUTED);}if(!s.error.isEmpty()){Design.text(body,s.error,14,500,Design.BROWN);Design.button(body,"Reload tags",false,job::inspect);}if(!s.result.isEmpty())Design.text(body,s.result,13,400,Design.MUTED);if(s.impacts.isEmpty()){Design.space(body,24);Design.text(body,"No saved tags yet",24,600,Design.INK);Design.space(body,12);Design.text(body,"Add a tag to a saved sleep record to compare your recorded periods.",14,400,Design.MUTED);return;}String shown=s.impacts.containsKey(selected)?selected:s.impacts.keySet().iterator().next();if(!s.busy)selected=shown;for(String name:s.impacts.keySet()){String label=name;PlanActivity.detail(body,"tag",name,s.impacts.get(name).tagged.count+" comparable tagged records",name.equals(selected)?"Selected":null,()->{selected=label;render();});}TagImpact impact=s.impacts.get(shown);RecordUi.heading(body,shown);Design.text(body,"Average recorded duration",14,600,Design.INK);comparison(body,"With tag",impact.tagged);comparison(body,"Without tag",impact.other);if(impact.tagged.count>0&&impact.other.count>0){long difference=impact.tagged.mean-impact.other.mean;Design.space(body,8);Design.text(body,(difference<0?"−":"+")+RecordUi.duration(Math.abs(difference))+" with this tag",20,600,Design.INK);}Design.space(body,12);Design.text(body,"Association only. Different dates, routines and other factors can explain a difference.",12,400,Design.MUTED);Design.text(body,impact.recorded+" phone/legacy · "+impact.manual+" manual · "+impact.imported+" imported records",12,400,Design.MUTED);Design.text(body,impact.skipped+" excluded: naps, unfinished/future, empty or overlapping records. Missing days add no samples.",12,400,Design.MUTED);RecordUi.heading(body,"Saved quantities");Design.text(body,impact.quantified+" tagged records with a quantity · "+(impact.tagged.count-impact.quantified)+" without",13,400,Design.MUTED);for(Map.Entry<String,List<Double>> group:impact.quantities.entrySet()){List<Double> values=group.getValue();double low=Collections.min(values),high=Collections.max(values);Design.text(body,new TagQuantity(low,group.getKey()).display()+" – "+new TagQuantity(high,group.getKey()).display()+" · "+values.size()+" records",14,500,Design.INK);TagImpact.QuantityGroup association=impact.quantityStats.get(group.getKey());Design.text(body,association.correlation==null?"Quantity comparison needs 3 varied values and durations.":"Quantity / duration correlation: "+String.format(java.util.Locale.getDefault(),"%.2f",association.correlation)+" · descriptive only",12,400,Design.MUTED);}LinearLayout footer=RecordUi.footer(body);Button renameButton=Design.button(footer,"Rename tag",true,()->openRename(selected));Button delete=Design.button(footer,"Delete tag from records",false,this::confirmDelete);renameButton.setEnabled(!s.busy);delete.setEnabled(!s.busy);}
 void comparison(LinearLayout body,String title,TagImpact.Group group){PlanActivity.detail(body,"report",title,group.count+" records",group.count==0?"No data":RecordUi.duration(group.mean),null);}
 void openRename(String value){if(job.state.busy)return;String reviewed=selected,expected=job.state.signatures.get(reviewed);if(expected==null)return;Dialog owned=new Dialog(this);dialog=owned;owned.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout body=Design.col(this);Design.pad(body,22,22);body.setBackground(Design.shape(this,Design.CREAM,24));Design.text(body,"Rename tag",22,600,Design.INK);rename=TagQuantityDialog.field(this,body,"New tag name",value);rename.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(40)});TextView error=Design.text(body,"",13,500,Design.BROWN);Design.button(body,"Save tag name",true,()->{try{String target=RecordDraft.tag(rename.getText().toString());job.change(reviewed,target,expected);selected=target;owned.dismiss();rename=null;render();}catch(IllegalArgumentException failure){error.setText(failure.getMessage());}});Design.button(body,"Cancel",false,owned::dismiss);show(owned,body);}
 void confirmDelete(){String reviewed=selected,expected=job.state.signatures.get(reviewed);if(expected==null||job.state.busy)return;Dialog owned=new Dialog(this);dialog=owned;owned.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout body=Design.col(this);Design.pad(body,22,22);body.setBackground(Design.shape(this,Design.CREAM,24));Design.text(body,"Delete “"+reviewed+"” tag?",21,600,Design.INK);Design.space(body,14);Design.text(body,"Remove this tag and its quantities from all saved record overlays. Sleep periods, notes and original source evidence stay unchanged. Restoring a measured original can restore tags in its original note.",14,400,Design.MUTED);Design.button(body,"Delete tag",true,()->{job.change(reviewed,null,expected);owned.dismiss();render();});Design.button(body,"Cancel",false,owned::dismiss);show(owned,body);}
 void show(Dialog owned,LinearLayout body){ScrollView scroll=new ScrollView(this);scroll.addView(body);owned.setContentView(scroll);owned.show();owned.getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(android.graphics.Color.TRANSPARENT));owned.getWindow().setLayout(getResources().getDisplayMetrics().widthPixels-Design.dp(this,32),-2);}
 @Override public void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putString("tag",selected);if(dialog!=null&&dialog.isShowing()&&rename!=null&&rename.isAttachedToWindow()){state.putBoolean("renaming",true);state.putString("rename",rename.getText().toString());}}
 @Override protected void onDestroy(){main.removeCallbacks(poll);if(dialog!=null)dialog.dismiss();super.onDestroy();}@Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);}
}
